import React,{useState,useEffect} from 'react';import {useNavigate} from 'react-router-dom';import {motion} from 'framer-motion';import {DollarSign,Building2,FileText,TrendingUp,Radio,Gift} from 'lucide-react';import {useConfig} from '../context/ConfigContext';import {useAuth} from '../context/AuthContext';import {useLang} from '../context/LangContext';import {LoadingPage} from '../components/Skeleton';import HomeSlider from '../components/HomeSlider';import axios from 'axios';
const API=process.env.REACT_APP_API_URL||'http://localhost:5000/api';
const c={hidden:{opacity:0},show:{opacity:1,transition:{staggerChildren:0.08}}};const i={hidden:{opacity:0,y:20},show:{opacity:1,y:0}};
export default function Home(){
  const [load,setLoad]=useState(true);const [users,setUsers]=useState([]);const {cfg}=useConfig();const {user}=useAuth();const {t}=useLang();const nav=useNavigate();
  useEffect(()=>{const tm=setTimeout(()=>setLoad(false),1200);axios.get(`${API}/auth/recent`).then(r=>setUsers(r.data)).catch(()=>{});return()=>clearTimeout(tm);},[]);
  if(load)return<LoadingPage/>;
  const acts=[{icon:DollarSign,label:t.deposit,desc:'أضف رصيد',path:'/deposit',bg:'bg-teal-50',col:'text-teal-600'},{icon:Building2,label:t.about,desc:'تعرف علينا',path:'/about',bg:'bg-blue-50',col:'text-blue-600'},{icon:FileText,label:t.withdraw,desc:'اسحب أرباحك',path:'/withdraw',bg:'bg-purple-50',col:'text-purple-600'},{icon:TrendingUp,label:t.records,desc:'المعاملات',path:'/mine',bg:'bg-orange-50',col:'text-orange-600'}];
  const activities=[{title:'تتبع القناة الرسمية',reward:'+0.10 USDT',icon:Gift,col:'text-pink-500',bg:'bg-pink-50'},{title:'مشاركة إعلانات تيليجرام',reward:'+2.00 USDT',icon:Gift,col:'text-blue-500',bg:'bg-blue-50'},{title:'مشاركة إعلانات الواتساب',reward:'+2.00 USDT',icon:Gift,col:'text-green-500',bg:'bg-green-50'},{title:'مشاركة إعلانات الفيسبوك',reward:'+5.00 USDT',icon:Gift,col:'text-indigo-500',bg:'bg-indigo-50'},{title:'تكبير مشاركة الإعلانات',reward:'+50.00 USDT',icon:Gift,col:'text-purple-500',bg:'bg-purple-50'}];
  return(
  <motion.div variants={c}initial="hidden"animate="show"className="pb-24 max-w-lg mx-auto">
  <motion.div variants={i}className="relative mx-2 rounded-b-3xl overflow-hidden text-white p-6"style={{background:`linear-gradient(135deg,${cfg.primaryColor},${cfg.secondaryColor})`}}>
  <div className="relative z-10"><motion.h1 initial={{x:20,opacity:0}}animate={{x:0,opacity:1}}className="text-2xl font-bold mb-1">برنامج</motion.h1><p className="text-white/80 text-sm">تعدين ZEC الاحترافي بأعلى عوائد</p></div>
  <motion.div animate={{rotate:[0,5,-5,0]}}transition={{repeat:Infinity,duration:6}}className="absolute top-2 left-4 opacity-10"><TrendingUp className="w-32 h-32"/></motion.div>
  </motion.div>
  <motion.div variants={i}className="grid grid-cols-2 gap-3 p-4">{acts.map((a,idx)=>(<motion.div key={idx}whileHover={{scale:1.03,y:-3}}whileTap={{scale:0.97}}onClick={()=>nav(a.path)}className={`${a.bg} rounded-2xl p-4 cursor-pointer shadow-sm hover:shadow-md transition border border-gray-100`}><div className={`w-11 h-11 rounded-xl ${a.bg} flex items-center justify-center mb-2`}><a.icon className={`w-5 h-5 ${a.col}`}/></div><h3 className="font-bold text-gray-800 text-sm">{a.label}</h3><p className="text-[11px] text-gray-500 mt-0.5">{a.desc}</p></motion.div>))}</motion.div>
  <motion.div variants={i}className="mx-4 bg-white rounded-xl p-3 shadow-sm flex items-center gap-2 text-xs text-gray-600 border border-gray-100"><TrendingUp className="w-4 h-4 text-green-500 shrink-0"/><span className="truncate">{cfg.tickerText}</span></motion.div>
  <HomeSlider/>
